import { Table, IntegerColumn, StringColumn, ReferenceColumn, DateTimeColumn, GuidColumn } from '../../db'

export const sys_wizard_choice = Table({
    allowWebServiceAccess: true,
    attributes: {
        forcePrimaryKeyOrdering: true,
    },
    label: 'Wizard Choices',
    name: 'sys_wizard_choice',
    schema: {
        order: IntegerColumn({
            default: '100',
            label: 'Order',
            maxLength: 40,
        }),
        sys_mod_count: IntegerColumn({
            label: [
                {
                    label: 'Updates',
                    plural: 'Updates',
                },
            ],
            maxLength: 40,
        }),
        text: StringColumn({
            label: 'Text',
            maxLength: 80,
        }),
        sys_created_by: StringColumn({
            label: [
                {
                    label: 'Created by',
                    plural: 'Created by',
                },
            ],
            maxLength: 40,
        }),
        sys_updated_by: StringColumn({
            label: [
                {
                    label: 'Updated by',
                    plural: 'Updated by',
                },
            ],
            maxLength: 40,
        }),
        answer: ReferenceColumn({
            label: 'Answer',
            maxLength: 32,
            referenceTable: 'sys_wizard_answer',
        }),
        value: StringColumn({
            label: 'Value',
            maxLength: 80,
        }),
        sys_created_on: DateTimeColumn({
            label: [
                {
                    label: 'Created',
                    plural: 'Created',
                },
            ],
            maxLength: 40,
        }),
        sys_updated_on: DateTimeColumn({
            label: [
                {
                    label: 'Updated',
                    plural: 'Updated',
                },
            ],
            maxLength: 40,
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                },
            ],
            maxLength: 32,
            primary: true,
        }),
    },
})
